import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Performance Meeting 2018-12-06","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-12-06","date":"2018-12-06T00:00:00.000Z","updated":"2018-12-07T00:00:00.000Z","tags":["Ceph","分布式存储","PG自动缩放器","缓冲区优化","编码基础设施优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-12-06.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-12-06.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Ceph_Performance_Meeting_2018-12-06.md"};function o(n,e,s,p,d,h){return t(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年12月6日</p><p><strong>参会人员</strong>： Sage、Radek、Skin Line、Hibi、Radek、Chuck、Sage、Adam、Casey、Jason等多位研发人员。</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储系统的性能优化，包括PG自动缩放器、缓冲区优化、编码基础设施优化等议题。</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><p><strong>1. PG自动缩放器</strong></p><ul><li>Sage介绍了新的PG自动缩放器模块，该模块基于John最初编写的模块，增加了新的池属性，如P基因组、目标大小字节和目标大小比率。</li><li>该模块允许用户根据预期的池大小自动调整PG数量，从而减少数据移动和优化性能。</li><li>Sage建议先合并管理接口重构的代码，然后再合并这个模块。</li></ul><p><strong>2. 缓冲区优化</strong></p><ul><li>Radek汇报了关于缓冲区跟踪基础设施的优化工作，包括缓冲区CSTR、CRC缓存和原子操作。</li><li>团队讨论了是否应该移除或禁用某些跟踪和缓存机制，以减少开销并提高性能。</li><li>Sage提出考虑移除CRC缓存，因为它在大多数情况下不会影响性能。</li></ul><p><strong>3. 编码基础设施优化</strong></p><ul><li>Sage介绍了对编码基础设施的优化工作，包括连续存储器类和零复制。</li><li>团队讨论了优化编码调用和消除不必要的汇编代码，以提高性能。</li><li>Sage建议先审查和合并这些更改。</li></ul><p><strong>4. 其他议题</strong></p><ul><li>讨论了关于在Ceph中优化原子操作的分支，以及是否应该移除XIO消息传递器。</li><li>讨论了关于优化旧编码基础设施的分支，以及是否应该继续优化这些代码。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>Sage建议先合并管理接口重构的代码，然后再合并PG自动缩放器模块。</li><li>团队决定审查和合并缓冲区优化和编码基础设施优化的代码。</li><li>讨论了是否应该移除或禁用某些跟踪和缓存机制，以及是否应该优化原子操作和编码基础设施。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>Sage将继续开发PG自动缩放器模块。</li><li>团队将继续审查和合并缓冲区优化和编码基础设施优化的代码。</li><li>团队将继续讨论是否应该移除或禁用某些跟踪和缓存机制，以及是否应该优化原子操作和编码基础设施。</li></ul>',17)])])}const c=a(r,[["render",o]]);export{g as __pageData,c as default};
